// MongoShellLexerInit initializes any static state used to implement MongoShellLexer. By default the
// static state used to implement the lexer is lazily initialized during the first call to
// NewMongoShellLexer(). You can call this function if you wish to initialize the static state ahead
// of time.
func MongoShellLexerInit() {
	staticData := &MongoShellLexerLexerStaticData
	staticData.once.Do(mongoshelllexerLexerInit)
}

// NewMongoShellLexer produces a new lexer instance for the optional input antlr.CharStream.
func NewMongoShellLexer(input antlr.CharStream) *MongoShellLexer {
	MongoShellLexerInit()
	l := new(MongoShellLexer)
	l.BaseLexer = antlr.NewBaseLexer(input)
	staticData := &MongoShellLexerLexerStaticData
	l.Interpreter = antlr.NewLexerATNSimulator(l, staticData.atn, staticData.decisionToDFA, staticData.PredictionContextCache)
	l.channelNames = staticData.ChannelNames
	l.modeNames = staticData.ModeNames
	l.RuleNames = staticData.RuleNames
	l.LiteralNames = staticData.LiteralNames
	l.SymbolicNames = staticData.SymbolicNames
	l.GrammarFileName = "MongoShellLexer.g4"
	// TODO: l.EOF = antlr.TokenEOF

	return l
}

